// Bundles cli/src/ into cli/factory.mjs, the one file an installer runs.
//
// WHY A COMMITTED BUNDLE
// The plugin installs by copying this repository (ADR 0014), and nothing in an
// install runs `npm ci`. So the CLI has to arrive runnable: its source may lean
// on dev dependencies, and the file that ships may not lean on any. esbuild
// inlines commander, and the bundle needs Node and nothing else. ADR 0073.
//
// WHY --check, AND WHY IT IS check:sync's SHAPE
// A committed generated file is the same hazard as the `.claude/skills/`
// mirror: edit the source, forget to rebuild, and the copy that actually runs
// is the old one with nothing saying so. `--check` builds in memory and fails
// when the result is not byte-for-byte the committed file, so a stale bundle is
// a red build rather than a stale install. `npm run check` runs it, and CI
// runs `npm run check:bundle`.
//
// A fresh build only equals the committed one when the toolchain is the same,
// which is what the exact pins in package.json and the lockfile are for. A
// green here on an esbuild other than the pinned one would mean nothing, so the
// version is compared before anything is built.
//
//   node scripts/build-cli.mjs           # write cli/factory.mjs
//   node scripts/build-cli.mjs --check   # fail if it differs from a fresh build
import { existsSync, readFileSync, writeFileSync } from 'node:fs'
import { dirname, join, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '..')
const ENTRY = 'cli/src/factory.ts'
const OUTPUT = 'cli/factory.mjs'
const check = process.argv.includes('--check')

// commander is MIT, and MIT asks that its notice travel with every copy. The
// bundle is a copy, and the package's LICENSE file stays behind in
// node_modules, which no installer has.
const BUNDLED_LICENCES = ['commander', '@commander-js/extra-typings']

let esbuild
try {
  esbuild = await import('esbuild')
} catch {
  console.error('esbuild is not installed, so the bundle cannot be built or checked.')
  console.error('Run `npm ci` first. The dev dependencies are pinned in package-lock.json.')
  process.exit(1)
}

const pinned = JSON.parse(readFileSync(join(ROOT, 'package.json'), 'utf8')).devDependencies.esbuild
if (esbuild.version !== pinned) {
  console.error(`esbuild ${esbuild.version} is installed but package.json pins ${pinned}.`)
  console.error('A bundle from another version differs for reasons that are not drift.')
  console.error('Run `npm ci` to install the pinned toolchain.')
  process.exit(1)
}

function licence(name) {
  // A path, not require.resolve: commander's `exports` does not expose its
  // package.json. Both are devDependencies of the root, so npm hoists them.
  const dir = join(ROOT, 'node_modules', name)
  const { version } = JSON.parse(readFileSync(join(dir, 'package.json'), 'utf8'))
  const text = readFileSync(join(dir, 'LICENSE'), 'utf8').replaceAll('\r\n', '\n').trim()
  return `${name}@${version}\n\n${text}`
}

const banner = [
  '#!/usr/bin/env node',
  '// GENERATED by scripts/build-cli.mjs from cli/src/. Do not edit this file:',
  '// edit the source and run `npm run build:cli`. `npm run check:bundle` fails',
  '// when this file is not what a fresh build produces. ADR 0073.',
].join('\n')

const footer = [
  '/*',
  ' * Bundled third-party code and its licences:',
  ...BUNDLED_LICENCES.flatMap((name) => ['', ...licence(name).split('\n')]).map((line) =>
    line ? ` * ${line}` : ' *',
  ),
  ' */',
].join('\n')

const result = await esbuild.build({
  absWorkingDir: ROOT,
  entryPoints: [ENTRY],
  bundle: true,
  platform: 'node',
  format: 'esm',
  target: 'node22',
  // No `minify`: an installer, or an agent reading a stack trace, should be
  // able to read what is running. The size difference is a few kilobytes.
  legalComments: 'none',
  banner: { js: banner },
  footer: { js: footer },
  write: false,
  outfile: OUTPUT,
  logLevel: 'warning',
})

const built = Buffer.from(result.outputFiles[0].contents)
const target = join(ROOT, OUTPUT)

if (!check) {
  writeFileSync(target, built)
  console.log(`Wrote ${OUTPUT} (${built.length} bytes).`)
  process.exit(0)
}

if (!existsSync(target)) {
  console.error(`${OUTPUT} does not exist. Run \`npm run build:cli\` and commit it.`)
  process.exit(1)
}

// Bytes, not text: .gitattributes keeps the checkout LF, so a CRLF here is a
// real difference in what ships and is worth failing on.
const committed = readFileSync(target)
if (committed.equals(built)) {
  console.log(`${OUTPUT} is what a fresh build of ${ENTRY} produces (${built.length} bytes).`)
  process.exit(0)
}

const committedLines = committed.toString('utf8').split('\n')
const builtLines = built.toString('utf8').split('\n')
const first = builtLines.findIndex((line, i) => line !== committedLines[i])
const at = first === -1 ? Math.min(builtLines.length, committedLines.length) : first
console.error(`${OUTPUT} differs from a fresh build of ${ENTRY}.\n`)
console.error(`  first difference at line ${at + 1}:`)
console.error(`    committed: ${JSON.stringify(committedLines[at] ?? '<end of file>')}`)
console.error(`    fresh:     ${JSON.stringify(builtLines[at] ?? '<end of file>')}`)
console.error(`\nEdit ${ENTRY}, never the bundle, then run:`)
console.error('  npm run build:cli')
console.error('\nIf you edited the bundle by hand, that change is about to be overwritten.')
console.error('Move it into the source first.')
process.exit(1)
